import { useAuth } from "@/_core/hooks/useAuth";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import {
  AlertTriangle,
  ArrowRight,
  Check,
  ChevronDown,
  ClipboardList,
  CircleAlert,
  Clock3,
  Factory,
  Filter,
  PackageCheck,
  Plus,
  RefreshCw,
  Search,
  ShoppingBag,
  ShieldCheck,
  Target,
  TrendingUp,
  Users,
  X,
} from "lucide-react";
import { useMemo, useState } from "react";
import { useLocation } from "wouter";

const CUSTOMER_TYPES = ["LOCAL", "INTERNATIONAL", "BUYER", "BRAND", "RESELLER", "OTHER"] as const;
const ORDER_STATUSES = ["DRAFT", "CONFIRMED", "IN PRODUCTION", "PRODUCTION COMPLETED", "QC", "READY", "DELIVERED", "CANCELLED"] as const;
const SIZES = ["XS", "S", "M", "L", "XL", "XXL", "3XL", "Other"] as const;
const todayInput = () => new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Dhaka" }).format(new Date());
const dateInput = (value: Date | string | number) => new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Dhaka" }).format(new Date(value));
const displayDate = (value: Date | string | number) => new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric", timeZone: "Asia/Dhaka" }).format(new Date(value));
const number = (value: unknown) => new Intl.NumberFormat("en-IN").format(Number(value) || 0);
const money = (value: unknown) => `৳${new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(Number(value) || 0)}`;

function statusTone(status: string) {
  if (["READY", "DELIVERED", "PRODUCTION COMPLETED"].includes(status)) return "success";
  if (["IN PRODUCTION", "CONFIRMED", "QC"].includes(status)) return "teal";
  if (["CANCELLED"].includes(status)) return "danger";
  return "neutral";
}

function StatusBadge({ status }: { status: string }) {
  return <span className={`status-badge status-${statusTone(status)}`}>{status.replace("PRODUCTION ", "PROD. ")}</span>;
}

function PageHeader({ eyebrow, title, description, action, actionLabel, onAction }: { eyebrow: string; title: string; description: string; action?: React.ReactNode; actionLabel?: string; onAction?: () => void }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow mb-2">{eyebrow}</p><h1 className="font-display text-3xl tracking-tight text-[#163247] sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#71818b]">{description}</p></div>{action ?? (actionLabel && <Button onClick={onAction} className="h-11 rounded-xl bg-[#ef6c4d] px-4 text-white hover:bg-[#df5c3d]"><Plus className="mr-2 h-4 w-4" />{actionLabel}</Button>)}</div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "teal" }: { label: string; value: string; detail: string; icon: typeof Target; tone?: "teal" | "orange" | "blue" | "red" }) {
  return <Card className="metric-card"><CardContent className="p-5"><div className="mb-5 flex items-start justify-between"><div className={`metric-icon metric-${tone}`}><Icon className="h-5 w-5" /></div><span className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#9ba8ad]">Today</span></div><p className="text-xs font-medium text-[#71818b]">{label}</p><p className="mt-1 text-2xl font-bold tracking-tight text-[#163247]">{value}</p><p className="mt-1 text-xs text-[#8d9aa0]">{detail}</p></CardContent></Card>;
}

function SectionHeading({ title, link, onLink }: { title: string; link?: string; onLink?: () => void }) {
  return <div className="mb-4 flex items-center justify-between"><h2 className="text-base font-semibold text-[#163247]">{title}</h2>{link && <button onClick={onLink} className="flex items-center gap-1 text-xs font-semibold text-[#1d7d73] hover:text-[#155c55]">{link}<ArrowRight className="h-3.5 w-3.5" /></button>}</div>;
}

function EmptyState({ title, description, action, onAction }: { title: string; description: string; action?: string; onAction?: () => void }) {
  return <div className="rounded-2xl border border-dashed border-[#d4e1e3] bg-[#fbfdfd] px-5 py-10 text-center"><div className="mx-auto mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-[#e9f2f1] text-[#1d7d73]"><PackageCheck className="h-5 w-5" /></div><p className="text-sm font-semibold text-[#163247]">{title}</p><p className="mx-auto mt-1 max-w-sm text-xs leading-5 text-[#8a9aa1]">{description}</p>{action && <Button onClick={onAction} variant="outline" className="mt-4 rounded-lg border-[#cbdedd] text-[#1d665e]">{action}</Button>}</div>;
}

function DashboardPage({ go }: { go: (path: string) => void }) {
  const { user } = useAuth();
  const canViewFinance = user?.role === "owner" || user?.role === "manager" || user?.role === "admin";
  const { data, isLoading, refetch } = trpc.dashboard.overview.useQuery();
  const { data: phase2 } = trpc.phase2.dashboard.useQuery();
  const { data: management } = trpc.management.overview.useQuery();
  const { data: finance } = trpc.commercial.dashboard.useQuery({ period: "TODAY" }, { enabled: canViewFinance });
  const metrics = data?.metrics;
  const attention = data?.orders?.filter(order => order.remaining > 0 && (new Date(order.deliveryDate) < new Date() || order.remaining / order.totalQuantity > 0.7)) ?? [];
  const qcAttention = phase2?.qcIssues ?? [];
  return <div className="mx-auto max-w-[1500px]">
    <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow mb-2">{new Intl.DateTimeFormat("en-GB", { weekday: "long", day: "2-digit", month: "long", timeZone: "Asia/Dhaka" }).format(new Date())}</p><h1 className="font-display text-3xl tracking-tight text-[#163247] sm:text-4xl">Good morning, keep it moving.</h1><p className="mt-2 text-sm text-[#71818b]">A clear view of today’s floor performance and order pipeline.</p></div><Button variant="outline" onClick={() => refetch()} className="h-10 w-fit rounded-xl border-[#cfdddf] bg-white text-[#4b6872]"><RefreshCw className="mr-2 h-4 w-4" />Refresh view</Button></div>
    {isLoading ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[1, 2, 3, 4].map(item => <div key={item} className="h-40 animate-pulse rounded-2xl bg-[#eaf1f2]" />)}</div> : <>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Production achievement" value={`${metrics?.achievement ?? 0}%`} detail={`${number(metrics?.actual)} actual of ${number(metrics?.target)} target`} icon={TrendingUp} tone="teal" /><MetricCard label="Pending production" value={number(metrics?.pending)} detail={`${number(metrics?.activeOrders)} active orders`} icon={Target} tone="orange" /><MetricCard label="Orders due soon" value={number(metrics?.dueSoon)} detail={`${number(metrics?.delayed)} currently delayed`} icon={Clock3} tone="red" /><MetricCard label="Workers present" value={number(metrics?.workersPresent)} detail={`${number(metrics?.good)} good pieces today`} icon={Users} tone="blue" /></div>
      <div className="mt-4 grid gap-3 grid-cols-2 sm:grid-cols-4"><div className="metric-card rounded-2xl p-4"><p className="text-xs text-[#71818b]">Present</p><p className="mt-1 text-xl font-bold text-[#163247]">{number(phase2?.manpower.present)}</p></div><div className="metric-card rounded-2xl p-4"><p className="text-xs text-[#71818b]">Absent</p><p className="mt-1 text-xl font-bold text-[#d46355]">{number(phase2?.manpower.absent)}</p></div><div className="metric-card rounded-2xl p-4"><p className="text-xs text-[#71818b]">Late</p><p className="mt-1 text-xl font-bold text-[#c78342]">{number(phase2?.manpower.late)}</p></div><div className="metric-card rounded-2xl p-4"><p className="text-xs text-[#71818b]">QC issues</p><p className="mt-1 text-xl font-bold text-[#d46355]">{number(qcAttention.length)}</p></div></div>
      <div className="mt-4 grid gap-2 grid-cols-2 sm:grid-cols-3 xl:grid-cols-6">{[["Cutting", "CUTTING", "/cutting"], ["Sewing", "SEWING", "/sewing"], ["DTF", "DTF", "/printing"], ["QC", "QC", "/qc"], ["Packing", "PACKING", "/packing"], ["Delivery", "DELIVERY", "/delivery"]].map(([label, stage, path]) => <button key={stage} onClick={() => go(path)} className="rounded-xl border border-[#e2ecee] bg-white px-3 py-3 text-left transition hover:border-[#bcd8d4]"><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#8a9ba1]">{label}</p><p className="mt-1 text-xl font-bold text-[#163247]">{number(phase2?.stageCounts?.[stage])}</p><p className="mt-1 text-[10px] text-[#789099]">active orders</p></button>)}</div>
      <div className="mt-4 grid gap-4 xl:grid-cols-[1.2fr_0.8fr]"><Card className="border-[#e2ecee]"><CardHeader><SectionHeading title="Factory today" /><p className="-mt-2 text-xs text-[#8b9aa0]">Management snapshot from the live production records.</p></CardHeader><CardContent className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Sewing target", management?.today.sewingTarget], ["Sewing actual", management?.today.sewingActual], ["Achievement", `${management?.today.achievement ?? 0}%`], ["Rejected", management?.today.rejected], ["QC pass", `${management?.today.qcPassRate ?? 0}%`], ["Packed", management?.today.packed], ["Delivered", management?.today.delivered], ["Active orders", management?.orderControl.activeOrders]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-[#f8fbfb] p-3"><p className="text-[10px] uppercase tracking-[0.08em] text-[#8d9da2]">{label as string}</p><p className="mt-1 text-lg font-bold text-[#163247]">{typeof value === "string" ? value : number(value)}</p></div>)}</CardContent></Card><Card className="border-[#f1ded5] bg-[#fffaf7]"><CardHeader><SectionHeading title="Management attention" link="Open alerts" onLink={() => go("/alerts")} /><p className="-mt-2 text-xs text-[#a1877d]">Highest-priority issues from the floor.</p></CardHeader><CardContent className="space-y-2">{management?.attention?.slice(0, 5).map(alert => <button key={alert.id} onClick={() => go("/alerts")} className="w-full rounded-xl border border-[#f0dfd8] bg-white/70 p-3 text-left hover:bg-white"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-[#65453c]">{alert.order ? `${alert.order} · ` : "Factory · "}{alert.problem}</p><span className={`status-badge ${alert.severity === "HIGH" ? "status-danger" : alert.severity === "MEDIUM" ? "status-orange" : "status-teal"}`}>{alert.severity}</span></div><p className="mt-1 text-[11px] text-[#9c7b71]">{alert.currentStage} · {alert.requiredAction}</p></button>)}{!management?.attention?.length && <div className="rounded-xl bg-white/70 p-4 text-center text-xs text-[#8aa19a]">No active management alerts.</div>}</CardContent></Card></div>
      <div className="mt-4 grid gap-2 grid-cols-2 sm:grid-cols-4 xl:grid-cols-7">{[["Due today", management?.orderControl.dueToday], ["Due soon", management?.orderControl.dueSoon], ["Overdue", management?.orderControl.overdue], ["Production done", management?.orderControl.productionCompleted], ["QC pending", management?.orderControl.qcPending], ["Packing pending", management?.orderControl.packingPending], ["Delivery pending", management?.orderControl.deliveryPending]].map(([label, value]) => <div key={label as string} className="rounded-xl border border-[#e2ecee] bg-white px-3 py-3"><p className="text-[10px] uppercase tracking-[0.08em] text-[#8d9da2]">{label as string}</p><p className="mt-1 text-xl font-bold text-[#163247]">{number(value)}</p></div>)}</div>
      {canViewFinance && <div className="mt-4 grid gap-4 xl:grid-cols-[1.2fr_0.8fr]"><Card className="border-[#e5e0d7] bg-[#fffdf8]"><CardHeader><SectionHeading title="Commercial Control" link="Open finance reports" onLink={() => go("/finance-reports")} /><p className="-mt-2 text-xs text-[#9b8d79]">Cash-control view only — not accounting profit.</p></CardHeader><CardContent className="grid grid-cols-2 gap-3 sm:grid-cols-5">{[["Order value", finance?.totalOrderValue], ["Payments received", finance?.paymentsReceived], ["Outstanding", finance?.outstanding], ["Expenses", finance?.expenses], ["Net cash movement", finance?.netCashMovement]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-white p-3"><p className="text-[10px] uppercase tracking-[0.08em] text-[#8d9da2]">{label as string}</p><p className="mt-1 text-lg font-bold text-[#163247]">{money(value)}</p></div>)}</CardContent></Card><Card className="border-[#f1ded5] bg-[#fffaf7]"><CardHeader><SectionHeading title="Payment attention" link="Open payments" onLink={() => go("/payments")} /><p className="-mt-2 text-xs text-[#a1877d]">Unpaid, overpaid, and high outstanding orders.</p></CardHeader><CardContent className="space-y-2">{finance?.attention?.slice(0, 4).map(row => <button key={row.orderId} onClick={() => go(`/orders/${row.orderId}`)} className="w-full rounded-xl border border-[#f0dfd8] bg-white/70 p-3 text-left hover:bg-white"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-[#65453c]">{row.order} · {row.customer}</p><span className={`status-badge ${row.paymentStatus === "OVERPAID" ? "status-danger" : row.paymentStatus === "UNPAID" ? "status-orange" : "status-teal"}`}>{row.paymentStatus}</span></div><p className="mt-1 text-[11px] text-[#9c7b71]">Outstanding {money(row.due)}</p></button>)}{!finance?.attention?.length && <div className="rounded-xl bg-white/70 p-4 text-center text-xs text-[#8aa19a]">No payment attention items.</div>}</CardContent></Card></div>}
      <div className="mt-7 grid gap-6 xl:grid-cols-[1.35fr_0.65fr]">
        <Card className="overflow-hidden border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardHeader className="border-b border-[#edf2f3] px-5 py-5"><SectionHeading title="Active order pipeline" link="View all orders" onLink={() => go("/orders")} /><p className="-mt-2 text-xs text-[#8b9aa0]">Good production is calculated from approved quantities after rejects.</p></CardHeader><CardContent className="p-0"><div className="hidden grid-cols-[1.1fr_1fr_1fr_0.8fr_0.9fr] gap-3 border-b border-[#edf2f3] bg-[#fbfcfc] px-5 py-3 text-[10px] font-semibold uppercase tracking-[0.12em] text-[#9aa7ab] sm:grid"><span>Order</span><span>Customer</span><span>Product</span><span>Progress</span><span>Delivery</span></div>{data?.orders?.length ? data.orders.slice(0, 6).map(order => <div key={order.id} className="grid gap-3 border-b border-[#f0f4f4] px-5 py-4 last:border-b-0 sm:grid-cols-[1.1fr_1fr_1fr_0.8fr_0.9fr] sm:items-center"><div><p className="text-sm font-semibold text-[#163247]">{order.orderCode}</p><p className="mt-1 text-xs text-[#93a0a5]">{number(order.totalQuantity)} pcs total</p></div><div className="text-sm text-[#516a74]">{order.customerName}</div><div><p className="text-sm text-[#36515d]">{order.product}</p><p className="mt-1 text-xs text-[#93a0a5]">{order.styleSku || "No SKU"}</p></div><div><div className="mb-1 flex justify-between text-[11px] text-[#789099]"><span>{number(order.produced)} good</span><span>{Math.round((order.produced / order.totalQuantity) * 100)}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#e8eeee]"><div className="h-full rounded-full bg-[#2c8b80]" style={{ width: `${Math.min(100, (order.produced / order.totalQuantity) * 100)}%` }} /></div></div><div className="flex items-center justify-between gap-2 sm:block"><p className={`text-sm ${new Date(order.deliveryDate) < new Date() ? "font-semibold text-[#dc6047]" : "text-[#516a74]"}`}>{displayDate(order.deliveryDate)}</p><StatusBadge status={order.status} /></div></div>) : <div className="p-5"><EmptyState title="No active orders yet" description="Create your first order to start tracking the factory pipeline." action="Create an order" onAction={() => go("/orders?new=1")} /></div>}</CardContent></Card>
        <Card className="border-[#f1ded5] bg-[#fffaf7] shadow-[0_8px_30px_rgba(141,79,48,0.04)]"><CardHeader className="px-5 pb-2 pt-5"><SectionHeading title="Needs attention" /><p className="-mt-2 text-xs text-[#a1877d]">Delayed orders, behind stages, and quality risks.</p></CardHeader><CardContent className="space-y-3 px-5 pb-5 pt-3">{attention.length || qcAttention.length ? <>{attention.slice(0, 3).map(order => <button onClick={() => go("/orders")} key={order.id} className="flex w-full items-start gap-3 rounded-xl border border-[#f0dfd8] bg-white/70 p-3 text-left hover:bg-white"><div className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-[#fff0e9] text-[#e06d4f]"><CircleAlert className="h-4 w-4" /></div><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#65453c]">{order.orderCode} · {order.customerName}</p><p className="mt-1 text-xs leading-5 text-[#9c7b71]">{new Date(order.deliveryDate) < new Date() ? "Delivery date has passed" : `${number(order.remaining)} pcs remaining to produce`}</p></div></button>)}{qcAttention.slice(0, 2).map(row => <button onClick={() => go("/qc")} key={`qc-${row.entry.id}`} className="flex w-full items-start gap-3 rounded-xl border border-[#f0dfd8] bg-white/70 p-3 text-left hover:bg-white"><div className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-[#fff0e9] text-[#e06d4f]"><CircleAlert className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-[#65453c]">{row.orderCode} · QC {row.entry.status}</p><p className="mt-1 text-xs text-[#9c7b71]">{number(row.entry.failedQuantity)} failed · {number(row.entry.reworkQuantity)} rework</p></div></button>)}</> : <div className="rounded-xl bg-white/70 p-5 text-center"><Check className="mx-auto mb-2 h-6 w-6 text-[#2f8c7d]" /><p className="text-sm font-semibold text-[#355c56]">Floor looks steady</p><p className="mt-1 text-xs text-[#8aa19a]">No urgent production alerts right now.</p></div>}<button onClick={() => go("/reports")} className="flex w-full items-center justify-between rounded-xl border border-dashed border-[#ebcfc4] px-3 py-3 text-xs font-semibold text-[#b26953] hover:bg-white"><span>Submit today’s floor report</span><ArrowRight className="h-4 w-4" /></button></CardContent></Card>
      </div>
      <div className="mt-7"><SectionHeading title="Production pipeline" link="Open cutting" onLink={() => go("/cutting")} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{phase2?.pipeline?.slice(0, 6).map(order => <button key={order.id} onClick={() => go(order.currentStage === "CUTTING" ? "/cutting" : order.currentStage === "DTF" ? "/printing" : order.currentStage === "QC" ? "/qc" : order.currentStage === "PACKING" ? "/packing" : order.currentStage === "DELIVERY" ? "/delivery" : "/sewing")} className="order-card text-left"><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-semibold text-[#163247]">{order.orderCode}</p><span className="status-badge status-teal">{order.currentStage}</span></div><p className="mt-1 truncate text-xs text-[#7d9098]">{order.customerName} · {order.product}</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#e8eeee]"><div className="h-full rounded-full bg-[#2c8b80]" style={{ width: `${order.progress}%` }} /></div><div className="mt-2 flex justify-between text-[11px] text-[#789099]"><span>{order.progress}% delivered</span><span>{number(order.remaining)} remaining</span></div></div></button>)}</div></div>
      <div className="mt-7"><SectionHeading title="Quick actions" /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[["New order", "Capture a customer order", "/orders", ShoppingBag], ["Production entry", "Log today’s output", "/production", Factory], ["Morning report", "Set the floor plan", "/reports", ClipboardList], ["Closing report", "Close the shift", "/reports", Check]].map(([label, sub, path, Icon]) => <button key={label as string} onClick={() => go(path as string)} className="quick-action"><div className="quick-icon"><Icon className="h-5 w-5" /></div><div className="text-left"><p className="text-sm font-semibold text-[#163247]">{label as string}</p><p className="mt-1 text-xs text-[#829198]">{sub as string}</p></div><ArrowRight className="ml-auto h-4 w-4 text-[#a6b3b7]" /></button>)}</div></div>
    </>}
  </div>;
}

function CustomersPage() {
  const { user } = useAuth();
  const canManage = user?.role === "owner" || user?.role === "manager" || user?.role === "admin";
  const [search, setSearch] = useState("");
  const [type, setType] = useState("ALL");
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [form, setForm] = useState({ customerName: "", companyName: "", phone: "", whatsapp: "", email: "", country: "Bangladesh", customerType: "LOCAL" as typeof CUSTOMER_TYPES[number], notes: "" });
  const query = trpc.customers.list.useQuery({ search, type });
  const utils = trpc.useUtils();
  const save = trpc.customers.create.useMutation({ onSuccess: () => { toast.success("Customer created"); setShowForm(false); reset(); utils.customers.list.invalidate(); }, onError: e => toast.error(e.message) });
  const update = trpc.customers.update.useMutation({ onSuccess: () => { toast.success("Customer updated"); setShowForm(false); reset(); utils.customers.list.invalidate(); }, onError: e => toast.error(e.message) });
  const remove = trpc.customers.remove.useMutation({ onSuccess: () => { toast.success("Customer removed"); utils.customers.list.invalidate(); }, onError: e => toast.error(e.message) });
  function reset() { setEditingId(null); setForm({ customerName: "", companyName: "", phone: "", whatsapp: "", email: "", country: "Bangladesh", customerType: "LOCAL", notes: "" }); }
  function startEdit(customer: NonNullable<typeof query.data>[number]) { setEditingId(customer.id); setForm({ customerName: customer.customerName, companyName: customer.companyName || "", phone: customer.phone || "", whatsapp: customer.whatsapp || "", email: customer.email || "", country: customer.country || "", customerType: customer.customerType, notes: customer.notes || "" }); setShowForm(true); }
  return <div className="mx-auto max-w-[1500px]"><PageHeader eyebrow="Relationships" title="Customers" description="Keep buyer and brand information close to the orders it powers." action={canManage ? <Button onClick={() => { reset(); setShowForm(true); }} className="h-11 rounded-xl bg-[#ef6c4d] text-white hover:bg-[#df5c3d]"><Plus className="mr-2 h-4 w-4" />New customer</Button> : undefined} />
    {showForm && canManage && <CustomerForm form={form} setForm={setForm} editing={Boolean(editingId)} busy={save.isPending || update.isPending} onCancel={() => { setShowForm(false); reset(); }} onSubmit={() => editingId ? update.mutate({ id: editingId, data: form }) : save.mutate(form)} />}
    <Card className="border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardContent className="p-4 sm:p-5"><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#97a7ad]" /><Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name, company, phone…" className="h-11 rounded-xl border-[#dbe6e8] pl-10" /></div><div className="relative"><Filter className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#97a7ad]" /><select value={type} onChange={e => setType(e.target.value)} className="h-11 w-full appearance-none rounded-xl border border-[#dbe6e8] bg-white pl-10 pr-9 text-sm text-[#4f6872] outline-none sm:w-48"><option value="ALL">All customer types</option>{CUSTOMER_TYPES.map(item => <option key={item}>{item}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#97a7ad]" /></div></div><div className="space-y-2">{query.data?.length ? query.data.map(customer => <div key={customer.id} className="customer-row"><div className="customer-avatar">{customer.customerName.slice(0, 1).toUpperCase()}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-semibold text-[#163247]">{customer.customerName}</p><span className="rounded-full bg-[#eaf3f1] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-[#2b766c]">{customer.customerType}</span>{customer.isDemo && <span className="rounded-full bg-[#f1f3f3] px-2 py-0.5 text-[10px] font-semibold text-[#87969c]">DEMO</span>}</div><p className="mt-1 truncate text-xs text-[#7d9098]">{customer.companyName || "Independent customer"} · {customer.phone || "No phone"}</p></div>{canManage && <div className="flex gap-2"><Button variant="outline" onClick={() => startEdit(customer)} className="h-9 rounded-lg border-[#d8e4e6] px-3 text-xs">Edit</Button>{user?.role === "owner" && <Button variant="outline" onClick={() => remove.mutate({ id: customer.id })} className="h-9 rounded-lg border-[#f1d4cc] px-3 text-xs text-[#c8654d]">Delete</Button>}</div>}</div>) : <EmptyState title="No customers found" description={canManage ? "Create a customer record before capturing an order." : "No customer records match this view."} action={canManage ? "Add customer" : undefined} onAction={() => setShowForm(true)} />}</div></CardContent></Card>
  </div>;
}

function CustomerForm({ form, setForm, editing, busy, onCancel, onSubmit }: { form: any; setForm: (value: any) => void; editing: boolean; busy: boolean; onCancel: () => void; onSubmit: () => void }) {
  const update = (key: string, value: string) => setForm({ ...form, [key]: value });
  return <Card className="mb-6 border-[#cfe4e0] bg-[#fbfefd]"><CardHeader className="flex flex-row items-center justify-between border-b border-[#e4efed] px-5 py-4"><div><CardTitle className="text-base text-[#163247]">{editing ? "Edit customer" : "New customer"}</CardTitle><p className="mt-1 text-xs text-[#82969a]">Use the customer record on future orders.</p></div><Button variant="ghost" size="icon" onClick={onCancel}><X className="h-4 w-4" /></Button></CardHeader><CardContent className="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-3"><Field label="Customer name *"><Input value={form.customerName} onChange={e => update("customerName", e.target.value)} placeholder="e.g. Aisha Rahman" /></Field><Field label="Company name"><Input value={form.companyName} onChange={e => update("companyName", e.target.value)} placeholder="Brand or company" /></Field><Field label="Customer type"><Select value={form.customerType} onChange={e => update("customerType", e.target.value)} options={CUSTOMER_TYPES} /></Field><Field label="Phone"><Input value={form.phone} onChange={e => update("phone", e.target.value)} placeholder="+880…" /></Field><Field label="WhatsApp"><Input value={form.whatsapp} onChange={e => update("whatsapp", e.target.value)} placeholder="+880…" /></Field><Field label="Email"><Input value={form.email} onChange={e => update("email", e.target.value)} placeholder="buyer@company.com" type="email" /></Field><Field label="Country"><Input value={form.country} onChange={e => update("country", e.target.value)} placeholder="Bangladesh" /></Field><div className="sm:col-span-2"><Field label="Notes"><Textarea value={form.notes} onChange={e => update("notes", e.target.value)} placeholder="Anything the floor team should know…" /></Field></div><div className="flex justify-end gap-2 sm:col-span-2 lg:col-span-3"><Button variant="outline" onClick={onCancel} className="rounded-lg">Cancel</Button><Button disabled={busy || !form.customerName.trim()} onClick={onSubmit} className="rounded-lg bg-[#1d7d73] text-white hover:bg-[#155c55]">{busy ? "Saving…" : editing ? "Save changes" : "Create customer"}</Button></div></CardContent></Card>;
}

function OrdersPage() {
  const [, setLocation] = useLocation();
  const { user } = useAuth();
  const canManage = user?.role === "owner" || user?.role === "manager" || user?.role === "admin";
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState("");
  const customers = trpc.customers.list.useQuery({ search: "", type: "ALL" });
  const orders = trpc.orders.list.useQuery();
  const utils = trpc.useUtils();
  const updateStatus = trpc.orders.updateStatus.useMutation({ onSuccess: () => { toast.success("Order status updated"); utils.orders.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: e => toast.error(e.message) });
  const remove = trpc.orders.remove.useMutation({ onSuccess: () => { toast.success("Order deleted"); utils.orders.list.invalidate(); }, onError: e => toast.error(e.message) });
  const create = trpc.orders.create.useMutation({ onSuccess: () => { toast.success("Order created"); setShowForm(false); utils.orders.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: e => toast.error(e.message) });
  const filtered = orders.data?.filter(row => `${row.order.orderCode} ${row.customerName} ${row.order.product}`.toLowerCase().includes(search.toLowerCase())) ?? [];
  return <div className="mx-auto max-w-[1500px]"><PageHeader eyebrow="Order control" title="Orders" description="Every order has a clear owner, date, quantity, and next action." action={canManage ? <Button onClick={() => setShowForm(v => !v)} className="h-11 rounded-xl bg-[#ef6c4d] text-white hover:bg-[#df5c3d]"><Plus className="mr-2 h-4 w-4" />New order</Button> : undefined} />{showForm && canManage && <OrderForm customers={customers.data ?? []} busy={create.isPending} onCancel={() => setShowForm(false)} onSubmit={data => create.mutate(data)} />}
    <Card className="border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardContent className="p-4 sm:p-5"><div className="relative mb-5 max-w-lg"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#97a7ad]" /><Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search orders, customers, products…" className="h-11 rounded-xl border-[#dbe6e8] pl-10" /></div><div className="space-y-3">{filtered.length ? filtered.map(({ order, customerName }) => <div key={order.id} className="order-card"><div className="flex flex-1 flex-col gap-3 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-[#163247]">{order.orderCode}</p><StatusBadge status={order.status} />{order.isDemo && <span className="rounded-full bg-[#f1f3f3] px-2 py-0.5 text-[10px] font-semibold text-[#87969c]">DEMO</span>}</div><p className="mt-1 truncate text-sm text-[#4e6872]">{order.product} <span className="text-[#9aa8ad]">· {customerName}</span></p><p className="mt-2 text-xs text-[#84969d]">Due {displayDate(order.deliveryDate)} · {number(order.totalQuantity)} pcs · {order.styleSku || "No SKU"}</p></div>{canManage && <div className="grid grid-cols-3 gap-4 border-t border-[#edf2f3] pt-3 sm:border-l sm:border-t-0 sm:pl-5 sm:pt-0"><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Order value</p><p className="mt-1 text-sm font-semibold text-[#35515c]">{money(order.orderValue)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Advance</p><p className="mt-1 text-sm font-semibold text-[#35515c]">{money(order.advance)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Status</p><select value={order.status} disabled={!canManage || updateStatus.isPending} onChange={e => updateStatus.mutate({ id: order.id, status: e.target.value as typeof ORDER_STATUSES[number] })} className="mt-1 max-w-[125px] bg-transparent text-xs font-semibold text-[#2b766c] outline-none"><option value={order.status}>{order.status}</option>{ORDER_STATUSES.filter(item => item !== order.status).map(item => <option key={item}>{item}</option>)}</select></div></div>}</div><div className="mt-3 flex gap-2 sm:ml-4 sm:mt-0"><Button variant="outline" onClick={() => setLocation(`/orders/${order.id}`)} className="h-8 rounded-lg border-[#cbdedd] px-3 text-xs text-[#1d665e]">Details</Button>{user?.role === "owner" && <Button variant="ghost" onClick={() => remove.mutate({ id: order.id })} className="h-8 px-2 text-xs text-[#c8654d]">Delete</Button>}</div></div>) : <EmptyState title="No orders yet" description={canManage ? "Create an order and the production pipeline will start here." : "No orders are available for this workspace."} action={canManage ? "Create order" : undefined} onAction={() => setShowForm(true)} />}</div></CardContent></Card>
  </div>;
}

function OrderForm({ customers, busy, onCancel, onSubmit }: { customers: any[]; busy: boolean; onCancel: () => void; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ customerId: customers[0]?.id || 0, orderDate: todayInput(), deliveryDate: todayInput(), product: "", productType: "Knit Garment", styleSku: "", totalQuantity: 0, orderValue: 0, estimatedCost: null as number | null, sewingCharge: 0, printingCharge: 0, otherCharge: 0, advance: 0, notes: "", status: "CONFIRMED" as typeof ORDER_STATUSES[number] });
  const [sizes, setSizes] = useState<Record<string, number>>(Object.fromEntries(SIZES.map(size => [size, 0])));
  const sizeTotal = Object.values(sizes).reduce((sum, value) => sum + (Number(value) || 0), 0);
  const update = (key: string, value: string | number | null) => setForm(prev => ({ ...prev, [key]: value }));
  function submit() { onSubmit({ ...form, customerId: Number(form.customerId), totalQuantity: Number(form.totalQuantity), orderValue: Number(form.orderValue), estimatedCost: form.estimatedCost === null ? null : Number(form.estimatedCost), sewingCharge: Number(form.sewingCharge), printingCharge: Number(form.printingCharge), otherCharge: Number(form.otherCharge), advance: Number(form.advance), sizes: SIZES.filter(size => Number(sizes[size]) > 0).map(size => ({ size, quantity: Number(sizes[size]) })) }); }
  return <Card className="mb-6 border-[#cfe4e0] bg-[#fbfefd]"><CardHeader className="flex flex-row items-center justify-between border-b border-[#e4efed] px-5 py-4"><div><CardTitle className="text-base text-[#163247]">New apparel order</CardTitle><p className="mt-1 text-xs text-[#82969a]">Size quantities can be less than the order total, but never more.</p></div><Button variant="ghost" size="icon" onClick={onCancel}><X className="h-4 w-4" /></Button></CardHeader><CardContent className="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-4"><Field label="Customer *"><Select value={String(form.customerId)} onChange={e => update("customerId", Number(e.target.value))} options={customers.map(c => ({ label: `${c.customerName}${c.companyName ? ` · ${c.companyName}` : ""}`, value: String(c.id) }))} /></Field><Field label="Order date *"><Input type="date" value={form.orderDate} onChange={e => update("orderDate", e.target.value)} /></Field><Field label="Delivery date *"><Input type="date" value={form.deliveryDate} onChange={e => update("deliveryDate", e.target.value)} /></Field><Field label="Initial status"><Select value={form.status} onChange={e => update("status", e.target.value)} options={ORDER_STATUSES.slice(0, 2)} /></Field><div className="sm:col-span-2"><Field label="Product *"><Input value={form.product} onChange={e => update("product", e.target.value)} placeholder="e.g. Oversized graphic t-shirt" /></Field></div><Field label="Product type"><Input value={form.productType} onChange={e => update("productType", e.target.value)} placeholder="Knit Garment + DTF" /></Field><Field label="Style / SKU"><Input value={form.styleSku} onChange={e => update("styleSku", e.target.value)} placeholder="TS-TEE-001" /></Field><Field label="Total quantity *"><Input type="number" min="1" value={form.totalQuantity || ""} onChange={e => update("totalQuantity", Number(e.target.value))} placeholder="0" /></Field><Field label="Order value"><Input type="number" min="0" step="0.01" value={form.orderValue || ""} onChange={e => update("orderValue", Number(e.target.value))} placeholder="0.00" /></Field><Field label="Estimated cost"><Input type="number" min="0" step="0.01" value={form.estimatedCost ?? ""} onChange={e => update("estimatedCost", e.target.value === "" ? null : Number(e.target.value))} placeholder="Optional" /></Field><div className="sm:col-span-2 lg:col-span-4"><div className="mb-2 flex items-center justify-between"><Label className="text-xs font-semibold text-[#516a74]">Size breakdown</Label><span className={`text-xs font-semibold ${sizeTotal > Number(form.totalQuantity) ? "text-[#d26048]" : "text-[#7d9298]"}`}>{number(sizeTotal)} / {number(form.totalQuantity)} allocated</span></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-8">{SIZES.map(size => <div key={size}><label className="mb-1 block text-[11px] font-medium text-[#8b9ba0]">{size}</label><Input type="number" min="0" value={sizes[size] || ""} onChange={e => setSizes({ ...sizes, [size]: Number(e.target.value) })} className="h-10" /></div>)}</div></div><Field label="Sewing charge"><Input type="number" min="0" value={form.sewingCharge || ""} onChange={e => update("sewingCharge", Number(e.target.value))} /></Field><Field label="Printing charge"><Input type="number" min="0" value={form.printingCharge || ""} onChange={e => update("printingCharge", Number(e.target.value))} /></Field><Field label="Other charge"><Input type="number" min="0" value={form.otherCharge || ""} onChange={e => update("otherCharge", Number(e.target.value))} /></Field><Field label="Advance"><Input type="number" min="0" value={form.advance || ""} onChange={e => update("advance", Number(e.target.value))} /></Field><div className="sm:col-span-2 lg:col-span-4"><Field label="Notes"><Textarea value={form.notes} onChange={e => update("notes", e.target.value)} placeholder="Print placement, fabric notes, delivery details…" /></Field></div><div className="flex justify-end gap-2 sm:col-span-2 lg:col-span-4"><Button variant="outline" onClick={onCancel} className="rounded-lg">Cancel</Button><Button disabled={busy || !form.customerId || !form.product.trim() || form.totalQuantity < 1 || sizeTotal > form.totalQuantity} onClick={submit} className="rounded-lg bg-[#1d7d73] text-white hover:bg-[#155c55]">{busy ? "Creating…" : "Create order"}</Button></div></CardContent></Card>;
}

function ProductionPage() {
  const { user } = useAuth();
  const orders = trpc.orders.list.useQuery();
  const production = trpc.production.list.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const create = trpc.production.create.useMutation({ onSuccess: result => { toast.success(`Production saved · ${number(result.goodQuantity)} good pieces`); setShowForm(false); utils.production.list.invalidate(); utils.orders.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: e => toast.error(e.message) });
  return <div className="mx-auto max-w-[1500px]"><PageHeader eyebrow="Floor output" title="Production" description="Record actual output once. Good quantity and order progress are calculated automatically." action={<Button onClick={() => setShowForm(v => !v)} className="h-11 rounded-xl bg-[#ef6c4d] text-white hover:bg-[#df5c3d]"><Plus className="mr-2 h-4 w-4" />Production entry</Button>} />{showForm && <ProductionForm orders={orders.data?.filter(row => !["DELIVERED", "CANCELLED"].includes(row.order.status)) ?? []} defaultOperatorId={user?.id} busy={create.isPending} onCancel={() => setShowForm(false)} onSubmit={data => create.mutate(data)} />}
    <div className="mb-6 grid gap-4 sm:grid-cols-3"><MetricCard label="Entries shown" value={number(production.data?.length)} detail="Search and review history below" icon={ClipboardList} tone="blue" /><MetricCard label="Good output" value={number(production.data?.reduce((sum, row) => sum + row.entry.actualProduction - row.entry.rejectedQuantity, 0))} detail="Across visible entries" icon={Check} tone="teal" /><MetricCard label="Rejected pieces" value={number(production.data?.reduce((sum, row) => sum + row.entry.rejectedQuantity, 0))} detail="Quality signal to review" icon={AlertTriangle} tone="red" /></div>
    <Card className="border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardContent className="p-4 sm:p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="text-base font-semibold text-[#163247]">Production history</h2><p className="mt-1 text-xs text-[#8b9aa0]">Newest entries first · good = actual − rejected.</p></div><Button variant="outline" onClick={() => production.refetch()} className="h-9 rounded-lg border-[#d8e4e6] px-3 text-xs"><RefreshCw className="mr-2 h-3.5 w-3.5" />Refresh</Button></div><div className="space-y-2">{production.data?.length ? production.data.map(({ entry, orderCode, product, operatorName }) => <div key={entry.id} className="production-row"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-[#163247]">{orderCode}</p><span className="text-xs text-[#8b9ba0]">{displayDate(entry.productionDate)}</span>{entry.isDemo && <span className="rounded-full bg-[#f1f3f3] px-2 py-0.5 text-[10px] font-semibold text-[#87969c]">DEMO</span>}</div><p className="mt-1 truncate text-xs text-[#71858d]">{product} · {operatorName || "Unknown operator"}</p></div><div className="grid grid-cols-3 gap-4 text-right"><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Target</p><p className="mt-1 text-sm font-semibold text-[#516a74]">{number(entry.productionTarget)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Good</p><p className="mt-1 text-sm font-semibold text-[#2b766c]">{number(entry.actualProduction - entry.rejectedQuantity)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-[#a0adb1]">Achieve</p><p className="mt-1 text-sm font-semibold text-[#d36a4c]">{entry.productionTarget ? Math.round((entry.actualProduction / entry.productionTarget) * 100) : 0}%</p></div></div></div>) : <EmptyState title="No production entries yet" description="Log the first run of the day to populate the factory output history." action="Add production entry" onAction={() => setShowForm(true)} />}</div></CardContent></Card>
  </div>;
}

function ProductionForm({ orders, defaultOperatorId, busy, onCancel, onSubmit }: { orders: any[]; defaultOperatorId?: number; busy: boolean; onCancel: () => void; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ orderId: orders[0]?.order.id || 0, productionDate: todayInput(), productionTarget: 0, actualProduction: 0, rejectedQuantity: 0, remarks: "" });
  const good = Math.max(0, Number(form.actualProduction) - Number(form.rejectedQuantity));
  const achievement = Number(form.productionTarget) ? Math.round((Number(form.actualProduction) / Number(form.productionTarget)) * 100) : 0;
  return <Card className="mb-6 border-[#cfe4e0] bg-[#fbfefd]"><CardHeader className="flex flex-row items-center justify-between border-b border-[#e4efed] px-5 py-4"><div><CardTitle className="text-base text-[#163247]">Record production</CardTitle><p className="mt-1 text-xs text-[#82969a]">The entry is checked against the order’s remaining quantity.</p></div><Button variant="ghost" size="icon" onClick={onCancel}><X className="h-4 w-4" /></Button></CardHeader><CardContent className="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-4"><div className="sm:col-span-2 lg:col-span-2"><Field label="Order *"><Select value={String(form.orderId)} onChange={e => setForm({ ...form, orderId: Number(e.target.value) })} options={orders.map(row => ({ label: `${row.order.orderCode} · ${row.order.product}`, value: String(row.order.id) }))} /></Field></div><Field label="Date *"><Input type="date" value={form.productionDate} onChange={e => setForm({ ...form, productionDate: e.target.value })} /></Field><Field label="Production target"><Input type="number" min="0" value={form.productionTarget || ""} onChange={e => setForm({ ...form, productionTarget: Number(e.target.value) })} /></Field><Field label="Actual production *"><Input type="number" min="0" value={form.actualProduction || ""} onChange={e => setForm({ ...form, actualProduction: Number(e.target.value) })} /></Field><Field label="Rejected quantity"><Input type="number" min="0" value={form.rejectedQuantity || ""} onChange={e => setForm({ ...form, rejectedQuantity: Number(e.target.value) })} /></Field><div className="rounded-xl bg-[#eaf3f1] p-3"><p className="text-[10px] font-semibold uppercase tracking-wide text-[#6d8c88]">Good quantity</p><p className="mt-1 text-xl font-bold text-[#1d665e]">{number(good)}</p></div><div className="rounded-xl bg-[#fff0e9] p-3"><p className="text-[10px] font-semibold uppercase tracking-wide text-[#a47e70]">Achievement</p><p className="mt-1 text-xl font-bold text-[#d36a4c]">{achievement}%</p></div><div className="sm:col-span-2 lg:col-span-4"><Field label="Remarks"><Textarea value={form.remarks} onChange={e => setForm({ ...form, remarks: e.target.value })} placeholder="Line, operator notes, defects, or blockers…" /></Field></div><div className="flex justify-end gap-2 sm:col-span-2 lg:col-span-4"><Button variant="outline" onClick={onCancel} className="rounded-lg">Cancel</Button><Button disabled={busy || !form.orderId || form.actualProduction < 0 || form.rejectedQuantity > form.actualProduction} onClick={() => onSubmit({ ...form, orderId: Number(form.orderId), productionTarget: Number(form.productionTarget), actualProduction: Number(form.actualProduction), rejectedQuantity: Number(form.rejectedQuantity), operatorId: defaultOperatorId })} className="rounded-lg bg-[#1d7d73] text-white hover:bg-[#155c55]">{busy ? "Saving…" : "Save production"}</Button></div></CardContent></Card>;
}

function ReportsPage() {
  const [type, setType] = useState<"MORNING" | "CLOSING">("MORNING");
  const reports = trpc.reports.list.useQuery();
  const dash = trpc.dashboard.overview.useQuery();
  const phase2 = trpc.phase2.dashboard.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const save = trpc.reports.save.useMutation({ onSuccess: () => { toast.success("Daily report saved"); setShowForm(false); utils.reports.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: e => toast.error(e.message) });
  const rows = reports.data?.filter(row => row.report.reportType === type) ?? [];
  return <div className="mx-auto max-w-[1200px]"><PageHeader eyebrow="Floor rhythm" title="Daily reports" description="A short morning plan and closing pulse keep the factory accountable without duplicate data entry." action={<Button onClick={() => setShowForm(v => !v)} className="h-11 rounded-xl bg-[#ef6c4d] text-white hover:bg-[#df5c3d]"><Plus className="mr-2 h-4 w-4" />{type === "MORNING" ? "Morning report" : "Closing report"}</Button>} />
    <Card className="mb-5 border-[#dceae8] bg-[#f8fcfb]"><CardContent className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4"><ReportStat label="Present manpower" value={phase2.data?.manpower.present ?? 0} /><ReportStat label="Sewing / good production" value={phase2.data?.pipeline?.reduce((sum, row) => sum + row.goodSewn, 0) ?? 0} /><ReportStat label="QC passed" value={phase2.data?.pipeline?.reduce((sum, row) => sum + row.passedQc, 0) ?? 0} /><ReportStat label="Delivery remaining" value={phase2.data?.pipeline?.reduce((sum, row) => sum + row.remaining, 0) ?? 0} /></CardContent></Card>
    <div className="mb-5 inline-flex rounded-xl border border-[#dbe7e8] bg-white p-1"><button onClick={() => setType("MORNING")} className={`rounded-lg px-4 py-2 text-xs font-semibold ${type === "MORNING" ? "bg-[#e9f2f1] text-[#1d665e]" : "text-[#819198]"}`}>Morning reports</button><button onClick={() => setType("CLOSING")} className={`rounded-lg px-4 py-2 text-xs font-semibold ${type === "CLOSING" ? "bg-[#fff0e9] text-[#b4614b]" : "text-[#819198]"}`}>Closing reports</button></div>
    {showForm && <ReportForm type={type} metrics={dash.data?.metrics} busy={save.isPending} onCancel={() => setShowForm(false)} onSubmit={data => save.mutate(data)} />}
    <div className="space-y-3">{rows.length ? rows.map(({ report, managerName }) => <Card key={report.id} className="border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardContent className="p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><div className="flex items-center gap-2"><p className="font-semibold text-[#163247]">{displayDate(report.reportDate)}</p><StatusBadge status={report.reportType === "MORNING" ? "CONFIRMED" : "PRODUCTION COMPLETED"} /></div><p className="mt-1 text-xs text-[#8a9ba1]">Submitted by {managerName || "Factory team"}{report.isDemo ? " · Demo data" : ""}</p></div><p className="text-xs text-[#9aa8ad]">{displayDate(report.createdAt)}</p></div>{report.reportType === "MORNING" ? <div className="grid gap-3 sm:grid-cols-4"><ReportStat label="Present" value={report.presentWorkers} /><ReportStat label="Absent" value={report.absentWorkers} /><ReportStat label="Late" value={report.lateWorkers} /><ReportStat label="Target" value={report.todaysProductionTarget} /></div> : <div className="grid gap-3 sm:grid-cols-4"><ReportStat label="Present" value={report.presentWorkers} /><ReportStat label="Actual" value={report.actualProduction} /><ReportStat label="Good" value={report.goodProduction} /><ReportStat label="Rejected" value={report.rejectedProduction} /></div>}<div className="mt-4 grid gap-3 border-t border-[#edf2f3] pt-4 sm:grid-cols-2"><div><p className="text-[10px] font-semibold uppercase tracking-wide text-[#a0adb1]">Issues</p><p className="mt-1 text-sm leading-6 text-[#546d76]">{report.importantIssues || report.issues || "No issues recorded."}</p></div><div><p className="text-[10px] font-semibold uppercase tracking-wide text-[#a0adb1]">Manager remarks</p><p className="mt-1 text-sm leading-6 text-[#546d76]">{report.managerRemarks || "No remarks recorded."}</p></div></div></CardContent></Card>) : <EmptyState title={`No ${type.toLowerCase()} reports yet`} description="Create a report for the floor team and it will stay available by date." action={`Create ${type.toLowerCase()} report`} onAction={() => setShowForm(true)} />}</div>
  </div>;
}

function ReportStat({ label, value }: { label: string; value: number }) { return <div className="rounded-xl bg-[#f7faf9] p-3"><p className="text-[10px] uppercase tracking-wide text-[#9aa8ad]">{label}</p><p className="mt-1 text-lg font-bold text-[#35515c]">{number(value)}</p></div>; }

function ReportForm({ type, metrics, busy, onCancel, onSubmit }: { type: "MORNING" | "CLOSING"; metrics?: any; busy: boolean; onCancel: () => void; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ reportDate: todayInput(), presentWorkers: 0, absentWorkers: 0, lateWorkers: 0, todaysProductionTarget: metrics?.target || 0, pendingProduction: metrics?.pending || 0, importantIssues: "", actualProduction: metrics?.actual || 0, goodProduction: metrics?.good || 0, rejectedProduction: 0, ordersCompleted: 0, issues: "", deliveryRequirement: "", managerRemarks: "" });
  const update = (key: string, value: string | number) => setForm(prev => ({ ...prev, [key]: value }));
  return <Card className="mb-6 border-[#cfe4e0] bg-[#fbfefd]"><CardHeader className="flex flex-row items-center justify-between border-b border-[#e4efed] px-5 py-4"><div><CardTitle className="text-base text-[#163247]">{type === "MORNING" ? "Morning report" : "Closing report"}</CardTitle><p className="mt-1 text-xs text-[#82969a]">Numbers from the current system view are pre-filled where possible.</p></div><Button variant="ghost" size="icon" onClick={onCancel}><X className="h-4 w-4" /></Button></CardHeader><CardContent className="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-4"><Field label="Report date *"><Input type="date" value={form.reportDate} onChange={e => update("reportDate", e.target.value)} /></Field><Field label="Present workers *"><Input type="number" min="0" value={form.presentWorkers || ""} onChange={e => update("presentWorkers", Number(e.target.value))} /></Field>{type === "MORNING" ? <><Field label="Absent workers"><Input type="number" min="0" value={form.absentWorkers || ""} onChange={e => update("absentWorkers", Number(e.target.value))} /></Field><Field label="Late workers"><Input type="number" min="0" value={form.lateWorkers || ""} onChange={e => update("lateWorkers", Number(e.target.value))} /></Field><Field label="Today’s production target"><Input type="number" min="0" value={form.todaysProductionTarget || ""} onChange={e => update("todaysProductionTarget", Number(e.target.value))} /></Field><Field label="Pending production"><Input type="number" min="0" value={form.pendingProduction || ""} onChange={e => update("pendingProduction", Number(e.target.value))} /></Field><div className="sm:col-span-2 lg:col-span-4"><Field label="Important issues"><Textarea value={form.importantIssues} onChange={e => update("importantIssues", e.target.value)} placeholder="Blockers, maintenance, staffing…" /></Field></div></> : <><Field label="Actual production"><Input type="number" min="0" value={form.actualProduction || ""} onChange={e => update("actualProduction", Number(e.target.value))} /></Field><Field label="Good production"><Input type="number" min="0" value={form.goodProduction || ""} onChange={e => update("goodProduction", Number(e.target.value))} /></Field><Field label="Rejected production"><Input type="number" min="0" value={form.rejectedProduction || ""} onChange={e => update("rejectedProduction", Number(e.target.value))} /></Field><Field label="Orders completed"><Input type="number" min="0" value={form.ordersCompleted || ""} onChange={e => update("ordersCompleted", Number(e.target.value))} /></Field><div className="sm:col-span-2"><Field label="Issues"><Textarea value={form.issues} onChange={e => update("issues", e.target.value)} placeholder="What needs follow-up tomorrow?" /></Field></div><div className="sm:col-span-2"><Field label="Delivery requirement"><Textarea value={form.deliveryRequirement} onChange={e => update("deliveryRequirement", e.target.value)} placeholder="Urgent dispatch or buyer requirement…" /></Field></div></>}<div className="sm:col-span-2 lg:col-span-4"><Field label="Manager remarks"><Textarea value={form.managerRemarks} onChange={e => update("managerRemarks", e.target.value)} placeholder="Short summary for the owner and next shift…" /></Field></div><div className="flex justify-end gap-2 sm:col-span-2 lg:col-span-4"><Button variant="outline" onClick={onCancel} className="rounded-lg">Cancel</Button><Button disabled={busy || !form.reportDate || form.presentWorkers < 0} onClick={() => onSubmit({ ...form, reportType: type })} className="rounded-lg bg-[#1d7d73] text-white hover:bg-[#155c55]">{busy ? "Saving…" : "Save report"}</Button></div></CardContent></Card>;
}

function UsersPage() {
  const users = trpc.users.list.useQuery();
  const utils = trpc.useUtils();
  const update = trpc.users.updateRole.useMutation({ onSuccess: () => { toast.success("Role updated"); utils.users.list.invalidate(); }, onError: e => toast.error(e.message) });
  return <div className="mx-auto max-w-[1000px]"><PageHeader eyebrow="Owner controls" title="Team access" description="Roles control who can manage customers, orders, production, and administrative controls." /><Card className="border-[#e2ecee] shadow-[0_8px_30px_rgba(28,63,77,0.04)]"><CardHeader><CardTitle className="flex items-center gap-2 text-base text-[#163247]"><ShieldCheck className="h-5 w-5 text-[#1d7d73]" />Workspace users</CardTitle></CardHeader><CardContent className="space-y-3">{users.data?.map(user => <div key={user.id} className="flex flex-col gap-3 rounded-xl border border-[#edf2f3] p-4 sm:flex-row sm:items-center"><div className="flex flex-1 items-center gap-3"><div className="customer-avatar">{(user.name || "U").slice(0, 1).toUpperCase()}</div><div><p className="text-sm font-semibold text-[#163247]">{user.name || "Unnamed user"}</p><p className="text-xs text-[#829198]">{user.email || user.openId}</p></div></div><select value={user.role === "admin" ? "owner" : user.role} onChange={e => update.mutate({ id: user.id, role: e.target.value as "owner" | "manager" | "factory_staff" })} className="h-10 rounded-lg border border-[#dbe6e8] bg-white px-3 text-sm text-[#516a74] outline-none sm:w-44"><option value="owner">Owner</option><option value="manager">Manager</option><option value="factory_staff">Factory staff</option></select></div>)}</CardContent></Card></div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <div><Label className="mb-1.5 block text-xs font-semibold text-[#516a74]">{label}</Label>{children}</div>; }
function Select({ value, onChange, options }: { value: string; onChange: React.ChangeEventHandler<HTMLSelectElement>; options: readonly (string | { label: string; value: string })[] }) { return <div className="relative"><select value={value} onChange={onChange} className="h-10 w-full appearance-none rounded-lg border border-[#dbe6e8] bg-white px-3 pr-8 text-sm text-[#516a74] outline-none focus:border-[#79b9b0] focus:ring-2 focus:ring-[#d8eeea]">{options.map(option => typeof option === "string" ? <option key={option} value={option}>{option}</option> : <option key={option.value} value={option.value}>{option.label}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#97a7ad]" /></div>; }

export default function Home() {
  const [, setLocation] = useLocation();
  const [location] = useLocation();
  const { user } = useAuth();
  const go = (path: string) => setLocation(path.split("?")[0]);
  const path = location.split("?")[0];
  if (!user) return null;
  if (path === "/orders") return <OrdersPage />;
  if (path === "/production") return <ProductionPage />;
  if (path === "/customers") return <CustomersPage />;
  if (path === "/reports") return <ReportsPage />;
  if (path === "/users" && (user.role === "owner" || user.role === "admin")) return <UsersPage />;
  return <DashboardPage go={go} />;
}
